select is((select count(*)::integer from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and (c.relkind = 'm' or (c.relkind = 'v' and not coalesce(c.reloptions @> array['security_invoker=true'], false))) and (has_table_privilege('authenticated', c.oid, 'SELECT') or has_table_privilege('anon', c.oid, 'SELECT'))), 0, 'No exposed view bypasses RLS');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prorettype = 'trigger'::regtype and (has_function_privilege('authenticated', p.oid, 'EXECUTE') or has_function_privilege('anon', p.oid, 'EXECUTE'))), 0, 'Privileged trigger functions cannot be called by clients');
create view public.rls_project_probe with (security_invoker = true) as select id from public.projects;
create view public.rls_notes_probe with (security_invoker = true) as select id from public.grader_notes;
grant select on public.rls_project_probe, public.rls_notes_probe to authenticated;
reset role;
