select throws_ok($$insert into public.projects (assignment_id, course_id, student_id) values ('00000000-0000-0000-0000-000000000023', '00000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000003')$$, '42501', null, 'Student cannot create for another owner');
